    good = sorted((s, float(v)) for s, v in x.items() if np.isfinite(v))
    if len(good) > 1:
        for i, (s, _) in enumerate(good):
            out[s] = (i + 1.0) / len(good)
    return out


def project(raw):
    # Projection onto a full-investment simplex with conservative per-asset bounds.
    w = {s: max(0.0, float(raw.get(s, 0.0))) for s in UNIVERSE}
    for _ in range(30):
        free = [s for s in UNIVERSE if MIN_W < w[s] < MAX_W]
        fixed = {s: w[s] for s in UNIVERSE if s not in free}
        if not free:
            break
        remainder = 1.0 - sum(fixed.values())
        total = sum(w[s] for s in free) or 1.0
        nw = dict(fixed)
        nw.update({s: remainder * w[s] / total for s in free})
        w = nw
        if all(MIN_W - 1e-9 <= w[s] <= MAX_W + 1e-9 for s in UNIVERSE):
            break
        for s in UNIVERSE:
            w[s] = min(MAX_W, max(MIN_W, w[s]))
    z = sum(w.values()) or 1.0
    return {s: w[s] / z for s in UNIVERSE}


