        invvol[s] = 1.0 / vol
    median = float(np.median(list(five.values())))
    peer = {s: v - median for s, v in five.items()}
    rawf = {"clv": clv, "peer": peer, "reversal": reversal, "momentum": momentum}
    ranked = {k: rank(v) for k, v in rawf.items()}
    score = {s: sum(weights.get(k, 0) * ranked[k].get(s, 0.5) for k in ranked) for s in UNIVERSE}

    # Medium-risk bullish posture; only a confirmed two-horizon SPX decline gets defensive.
    spx = market.get("SPX")
    if spx is not None and spx[0][-1] < spx[0][-21] and spx[0][-1] < spx[0][-6]:
        for s in ("XAU", "US10Y", "CN10Y"): score[s] += 0.18
        for s in ("BTC", "ETH", "WTI"): score[s] = max(0.05, score[s] - 0.10)
    avg = np.mean(list(invvol.values())) or 1.0
    raw = {s: max(0.01, score[s]) * (0.78 + 0.22 * invvol.get(s, avg) / avg) for s in UNIVERSE}
    target = project(raw)
    vals = np.array([score[s] for s in UNIVERSE])
    scale = max(float(vals.std()), 1e-12)
    forecast = {s: float(0.01 * (score[s] - vals.mean()) / scale) for s in UNIVERSE}
    ids = [fid for fid, _, _ in factors]
    rebalance_to_weights(target, forecast_returns=forecast, factor_ids=ids, horizon_days=10)
    _bars_since_rebalance = 0

